use crate::aap::caps::inference_llm;

struct Node;

/// Truncate `s` to at most `max` bytes, never splitting a UTF-8 char.
fn truncate_bytes(s: &str, max: usize) -> String {
    if s.len() <= max {
        return s.to_string();
    }
    let mut end = max;
    while end > 0 && !s.is_char_boundary(end) {
        end -= 1;
    }
    s[..end].to_string()
}

/// Map a model label to the closed intent set. Anything we don't recognise
/// collapses to `Unknown` — the enum has no "other" case, so adversarial text
/// cannot widen the set.
fn parse_intent(label: &str) -> Intent {
    let l = label.trim().to_ascii_lowercase();
    // Take the first non-empty line/word-ish token the model emitted.
    let first = l.lines().next().unwrap_or("").trim();
    match first {
        s if s.contains("billing") => Intent::BillingQuestion,
        s if s.contains("technical") || s.contains("support") => Intent::TechnicalSupport,
        s if s.contains("account") => Intent::AccountChange,
        s if s.contains("general") || s.contains("inquiry") => Intent::GeneralInquiry,
        _ => Intent::Unknown,
    }
}

impl Guest for Node {
    fn run(message: RawMessage) -> CustomerQuery {
        // Precondition on the input: len(value.text) <= 4000. The node is only
        // ever given inputs that satisfy its `requires`; we clamp defensively so
        // the prompt we build is bounded regardless.
        let text = truncate_bytes(&message.text, 4000);

        let system = "You classify a customer support message. \
Reply with exactly one of these labels on the first line and nothing else: \
billing_question, technical_support, account_change, general_inquiry, unknown.";

        let label = inference_llm::infer(system, &text, "classify");

        // ensures: intent in the closed set — enforced by the enum + this mapping.
        let intent = parse_intent(&label);

        // ensures: len(question) <= 512. The question is the (bounded) customer
        // text; truncate to the post-condition bound.
        let question = truncate_bytes(&text, 512);

        CustomerQuery {
            intent,
            entities: Vec::new(),
            question,
        }
    }
}

export!(Node);
```

